  const [showReturnReadingPrompt, setShowReturnReadingPrompt] = useState(false);
  const [returnReadingFiles, setReturnReadingFiles] = useState<Array<{id: number; name: string; folder: string; originalName: string; displayName: string; objectPath: string; listened?: boolean; lastChunkIndex?: number; totalChunks?: number; checkedChunks?: string}>>([]);
  const [selectedReturnFile, setSelectedReturnFile] = useState<number | null>(null);
  const returnPromptShown = useRef(false);

  useEffect(() => {
    if (returnPromptShown.current) return;
    returnPromptShown.current = true;

    if (window.location.hostname.endsWith('.replit.app')) {
      localStorage.setItem('replitLastActiveTime', String(Date.now()));
      return;
    }

    const lastActive = parseInt(localStorage.getItem('replitLastActiveTime') || '0', 10);
    const now = Date.now();
    const twoHoursMs = 2 * 60 * 60 * 1000;
    const forceWelcome = new URLSearchParams(window.location.search).has('forceWelcome');
    if (!forceWelcome && lastActive > 0 && (now - lastActive) < twoHoursMs) {
      localStorage.setItem('replitLastActiveTime', String(now));
      return;
    }

    Promise.all([
      fetch("/api/files").then(r => r.json()),
      fetch("/api/semester", { credentials: 'include' }).then(r => r.ok ? r.json() : null),
    ])
      .then(([files, semSettings]: [any[], any]) => {
        let currentWeekNum = 1;
        if (semSettings?.semesterStartDate) {
          currentWeekNum = getWeekNumber(new Date(), new Date(semSettings.semesterStartDate), semSettings.readingWeekStart);
        }

        const isPartial = (f: any) => {
          if (f.listened) return false;
          const hasCheckedChunks = (() => {
            if (!f.checkedChunks) return false;
            try { const arr = JSON.parse(f.checkedChunks); return Array.isArray(arr) && arr.length > 0; } catch { return false; }
          })();
          const hasLastChunk = f.lastChunkIndex != null && f.lastChunkIndex > 0;
          if (!hasCheckedChunks && !hasLastChunk) return false;
          if (f.totalChunks && f.totalChunks > 0) {
            if (hasCheckedChunks) {
              try { const arr = JSON.parse(f.checkedChunks); if (arr.length >= f.totalChunks) return false; } catch {}
            }
            if (hasLastChunk && f.lastChunkIndex >= f.totalChunks) return false;
          }
          return true;
        };

        const currentWeekFiles = files.filter((f: any) => {
          const weekMatch = f.folder?.match(/week-(\d+)/i);
          if (!weekMatch || parseInt(weekMatch[1], 10) !== currentWeekNum) return false;
          if (f.listened) return false;
          return true;
        });

        const partialCurrentWeek = currentWeekFiles.filter(isPartial);
        const unlistenedCurrentWeek = currentWeekFiles.filter((f: any) => !isPartial(f));

        const orderedFiles = [...partialCurrentWeek, ...unlistenedCurrentWeek];

        if (orderedFiles.length > 0) {
          const mapped = orderedFiles.map((f: any) => ({
            id: f.id,
            name: f.displayName || f.originalName || 'Unknown',
            folder: f.folder || '',
            originalName: f.originalName || '',
            displayName: f.displayName || f.originalName || '',
            objectPath: f.objectPath || '',
            listened: f.listened,
            lastChunkIndex: f.lastChunkIndex,
            totalChunks: f.totalChunks,
            checkedChunks: f.checkedChunks,
          }));
          setReturnReadingFiles(mapped);
          setSelectedReturnFile(mapped[0].id);
        }
        if (orderedFiles.length > 0 && window.location.hostname === 'localhost') {
          setShowReturnReadingPrompt(true);
        }
      })
      .catch(() => {});

    const interval = setInterval(() => {
      localStorage.setItem('replitLastActiveTime', String(Date.now()));
    }, 60000);
    return () => clearInterval(interval);
  }, []);

  // Share link state
