  const startVoiceInput = useCallback(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      toast({ title: "Not supported", description: "Speech recognition is not supported in this browser." });
      return;
    }
    const activeEl = document.activeElement as HTMLInputElement | HTMLTextAreaElement | null;
    if (activeEl && (activeEl.tagName === 'INPUT' || activeEl.tagName === 'TEXTAREA')) {
      voiceTargetRef.current = activeEl;
    } else if (lastFocusedInputRef.current && lastFocusedInputRef.current.isConnected) {
      voiceTargetRef.current = lastFocusedInputRef.current;
    } else {
      voiceTargetRef.current = null;
    }
    const targetInfo = voiceTargetRef.current
      ? `${voiceTargetRef.current.tagName}[${voiceTargetRef.current.getAttribute('data-testid') || voiceTargetRef.current.name || voiceTargetRef.current.placeholder || 'unknown'}]`
      : 'NO TARGET';
    console.log('[Voice] Starting recognition, target:', targetInfo);
    voiceStoppingRef.current = false;
    voiceFinalTextRef.current = '';
    const recognition = new SpeechRecognition();
    recognition.continuous = true;
    recognition.interimResults = true;
    recognition.lang = 'en-US';
    recognition.onresult = (event: any) => {
      let interim = '';
      for (let i = event.resultIndex; i < event.results.length; i++) {
        const t = event.results[i][0].transcript;
        if (event.results[i].isFinal) {
          voiceFinalTextRef.current += t;
        } else {
          interim += t;
        }
      }
      setVoiceTranscript(voiceFinalTextRef.current + interim);
    };
    recognition.onerror = (event: any) => {
      console.error('[Voice] Recognition error:', event.error);
      if (event.error === 'no-speech' || event.error === 'audio-capture') {
        return;
      }
      if (event.error === 'aborted') return;
      voiceStoppingRef.current = true;
      setIsVoiceListening(false);
    };
    recognition.onend = () => {
      if (!voiceStoppingRef.current) {
        try {
          recognition.start();
          return;
        } catch (e) {
          console.warn('[Voice] Failed to restart recognition:', e);
        }
      }
      setIsVoiceListening(false);
      const text = voiceFinalTextRef.current;
      if (text && voiceTargetRef.current && voiceTargetRef.current.isConnected) {
        const el = voiceTargetRef.current;
        el.focus();
        try {
          const nativeInputValueSetter = Object.getOwnPropertyDescriptor(
            el.tagName === 'TEXTAREA' ? window.HTMLTextAreaElement.prototype : window.HTMLInputElement.prototype,
            'value'
          )?.set;
          const start = el.selectionStart ?? el.value.length;
          const end = el.selectionEnd ?? el.value.length;
          const newValue = el.value.substring(0, start) + text + el.value.substring(end);
          if (nativeInputValueSetter) {
            nativeInputValueSetter.call(el, newValue);
          } else {
            el.value = newValue;
          }
          el.selectionStart = el.selectionEnd = start + text.length;
          el.dispatchEvent(new Event('input', { bubbles: true }));
          el.dispatchEvent(new Event('change', { bubbles: true }));
          toast({ title: 'Voice inserted', description: text.length > 60 ? text.substring(0, 60) + '...' : text });
        } catch (err) {
          console.error('[Voice] Insert failed:', err);
          navigator.clipboard?.writeText(text);
          toast({ title: 'Copied to clipboard instead', description: text.length > 60 ? text.substring(0, 60) + '...' : text });
        }
      } else if (text) {
        navigator.clipboard?.writeText(text).then(() => {
          toast({ title: 'No text field selected — copied to clipboard', description: text.length > 80 ? text.substring(0, 80) + '...' : text });
        }).catch(() => {
          toast({ title: 'Voice transcript (no field targeted)', description: text });
        });
      } else {
        toast({ title: 'No speech detected' });
      }
      setVoiceTranscript('');
      voiceTargetRef.current = null;
      voiceFinalTextRef.current = '';
    };
    voiceRecognitionRef.current = recognition;
    recognition.start();
    setIsVoiceListening(true);
    setVoiceTranscript('');
  }, [toast]);

