  // Handle row resize
  const handleHwGroupBarDragStart = (e: React.MouseEvent | React.TouchEvent) => {
    e.preventDefault();
    e.stopPropagation();
    const startX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    hwGroupBarDragRef.current = { startX, startWidth: hwGroupBarWidth };
    const onMove = (ev: MouseEvent | TouchEvent) => {
      if (!hwGroupBarDragRef.current) return;
      const clientX = 'touches' in ev ? ev.touches[0].clientX : (ev as MouseEvent).clientX;
      const dx = clientX - hwGroupBarDragRef.current.startX;
      const newW = Math.max(50, Math.min(250, hwGroupBarDragRef.current.startWidth + dx));
      setHwGroupBarWidth(newW);
    };
    const onUp = () => {
      document.removeEventListener('mousemove', onMove);
      document.removeEventListener('mouseup', onUp);
      document.removeEventListener('touchmove', onMove);
      document.removeEventListener('touchend', onUp);
      setHwGroupBarWidth(w => { localStorage.setItem('hwGroupBarWidth', String(w)); const sw2 = window.screen.width, sh2 = window.screen.height, pr2 = window.devicePixelRatio || 1; localStorage.setItem(`hwGroupBarWidth_device_${sw2}x${sh2}@${pr2}`, String(w)); fetch('/api/ui-settings/hwGroupBarWidth', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ value: w }) }).catch(() => {}); return w; });
      hwGroupBarDragRef.current = null;
    };
    document.addEventListener('mousemove', onMove);
    document.addEventListener('mouseup', onUp);
    document.addEventListener('touchmove', onMove);
    document.addEventListener('touchend', onUp);
  };

  const handleHwDividerDragStart = (e: React.MouseEvent | React.TouchEvent) => {
    e.preventDefault();
    e.stopPropagation();
    const container = homeworkSectionRef.current;
    if (!container) return;
    const containerWidth = container.getBoundingClientRect().width;
    const startX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    hwDividerDragRef.current = { startX, startPercent: hwDividerPercent, containerWidth };
    const onMove = (ev: MouseEvent | TouchEvent) => {
      if (!hwDividerDragRef.current) return;
      const clientX = 'touches' in ev ? ev.touches[0].clientX : (ev as MouseEvent).clientX;
      const dx = clientX - hwDividerDragRef.current.startX;
      const dpct = (dx / hwDividerDragRef.current.containerWidth) * 100;
      const newPct = Math.max(20, Math.min(63, hwDividerDragRef.current.startPercent + dpct));
      setHwDividerPercent(newPct);
    };
    const onUp = () => {
      document.removeEventListener('mousemove', onMove);
      document.removeEventListener('mouseup', onUp);
      document.removeEventListener('touchmove', onMove);
      document.removeEventListener('touchend', onUp);
      setHwDividerPercent(pct => { localStorage.setItem('hwDividerPercent', String(pct)); return pct; });
      hwDividerDragRef.current = null;
    };
    document.addEventListener('mousemove', onMove);
    document.addEventListener('mouseup', onUp);
    document.addEventListener('touchmove', onMove);
    document.addEventListener('touchend', onUp);
  };

  const handleRowResizeStart = (e: React.MouseEvent | React.TouchEvent, rowType: 'allDay' | 'course' | 'other' | 'timeSlot', hourIndex?: number) => {
    e.preventDefault();
    e.stopPropagation();
    let startHeight: number;
    if (rowType === 'allDay') {
      startHeight = gridSizes.allDayRowHeight;
    } else if (rowType === 'course') {
      startHeight = gridSizes.courseRowHeight;
    } else if (rowType === 'other') {
      startHeight = gridSizes.otherRowHeight;
    } else if (hourIndex !== undefined) {
      startHeight = gridSizes.timeSlotHeights[hourIndex];
    } else {
      startHeight = gridSizes.timeSlotHeight;
    }
    const { clientY } = getPointerXY(e);
    setRowResizing({
      isResizing: true,
      rowType,
      hourIndex,
      startY: clientY,
      startHeight
    });
  };
  
  // Global move/end handlers for resizing (mouse + touch)
  useEffect(() => {
    const handleMove = (e: MouseEvent | TouchEvent) => {
      const { clientX, clientY } = getPointerXY(e);
      if (columnResizing?.isResizing) {
        const delta = clientX - columnResizing.startX;
        if (columnResizing.columnIndex === -1) {
          const newWidth = Math.max(115, Math.min(200, columnResizing.startWidth + delta));
          setGridSizes(prev => ({ ...prev, timeColumnWidth: newWidth }));
        } else if (columnResizing.columnIndex === -2) {
          const newWidth = Math.max(50, Math.min(150, columnResizing.startWidth + delta));
          setGridSizes(prev => ({ ...prev, moduleColumnWidth: newWidth }));
        } else {
          const newWidths = [...gridSizes.dayColumnWidths];
          const newProportion = Math.max(0.5, columnResizing.startWidth + delta / 100);
          newWidths[columnResizing.columnIndex] = newProportion;
          setGridSizes(prev => ({ ...prev, dayColumnWidths: newWidths }));
        }
      }
      if (rowResizing?.isResizing) {
        const delta = clientY - rowResizing.startY;
        const newHeight = Math.max(20, rowResizing.startHeight + delta);
        if (rowResizing.rowType === 'allDay') {
          setGridSizes(prev => ({ ...prev, allDayRowHeight: Math.min(100, newHeight) }));
        } else if (rowResizing.rowType === 'course') {
          setGridSizes(prev => ({ ...prev, courseRowHeight: Math.min(82, newHeight) }));
        } else if (rowResizing.rowType === 'other') {
          setGridSizes(prev => ({ ...prev, otherRowHeight: Math.min(150, newHeight) }));
        } else if (rowResizing.rowType === 'timeSlot' && rowResizing.hourIndex !== undefined) {
          setGridSizes(prev => {
            const newHeights = [...prev.timeSlotHeights];
            newHeights[rowResizing.hourIndex!] = Math.max(24, Math.min(150, newHeight));
            return { ...prev, timeSlotHeights: newHeights };
          });
        } else if (rowResizing.rowType === 'timeSlot') {
          setGridSizes(prev => ({ ...prev, timeSlotHeight: Math.min(100, newHeight) }));
        }
      }
      if (isResizingHomework && resizingHomeworkRef.current) {
        const delta = resizingHomeworkRef.current.startX - clientX;
        const newReduction = Math.max(120, Math.min(window.innerWidth * 0.45, resizingHomeworkRef.current.startReduction + delta));
        setCalendarReduction(newReduction);
        setCalendarReductionUserSet(true);
      }
    };
    
    const handleEnd = () => {
      if (isResizingHomework && resizingHomeworkRef.current) {
        const oldReduction = resizingHomeworkRef.current.startReduction;
        if (oldReduction !== calendarReduction) {
          setUndoStack(prev => [{ type: 'resize', description: 'Resize calendar/homework width', data: { resizeType: 'width', oldValue: oldReduction, newValue: calendarReduction } }, ...prev]);
          setRedoStack([]);
        }
        setIsResizingHomework(false);
        resizingHomeworkRef.current = null;
        const curRed = calendarReductionRef.current;
        localStorage.setItem('calendarReduction', String(curRed));
        const sw = window.screen.width, sh = window.screen.height, pr = window.devicePixelRatio || 1;
        localStorage.setItem(`calendarReduction_device_${sw}x${sh}@${pr}`, String(curRed));
      } else if (isResizingHomework) {
        setIsResizingHomework(false);
        resizingHomeworkRef.current = null;
        const curRed2 = calendarReductionRef.current;
        localStorage.setItem('calendarReduction', String(curRed2));
        const sw = window.screen.width, sh = window.screen.height, pr = window.devicePixelRatio || 1;
        localStorage.setItem(`calendarReduction_device_${sw}x${sh}@${pr}`, String(curRed2));
      }
      if (columnResizing?.isResizing || rowResizing?.isResizing) {
        setTimeout(() => {
          const cur = JSON.stringify(gridSizes);
          localStorage.setItem('gridSizes', cur);
          const sw = window.screen.width, sh = window.screen.height, pr = window.devicePixelRatio || 1;
          localStorage.setItem(`gridSizes_device_${sw}x${sh}@${pr}`, cur);
        }, 0);
      }
      setColumnResizing(null);
      setRowResizing(null);
    };
    
    if (columnResizing?.isResizing || rowResizing?.isResizing || isResizingHomework) {
      document.addEventListener('mousemove', handleMove);
      document.addEventListener('mouseup', handleEnd);
      document.addEventListener('touchmove', handleMove, { passive: false });
      document.addEventListener('touchend', handleEnd);
      document.body.style.cursor = (columnResizing?.isResizing || isResizingHomework) ? 'col-resize' : 'row-resize';
      document.body.style.userSelect = 'none';
    }
    
    return () => {
      document.removeEventListener('mousemove', handleMove);
      document.removeEventListener('mouseup', handleEnd);
      document.removeEventListener('touchmove', handleMove);
      document.removeEventListener('touchend', handleEnd);
      document.body.style.cursor = '';
      document.body.style.userSelect = '';
    };
  }, [columnResizing, rowResizing, gridSizes.dayColumnWidths, isResizingHomework, calendarReduction]);
  
  const [draggedBox, setDraggedBox] = useState<string | null>(null);
  const [thisWeekBoxHeight, setThisWeekBoxHeight] = useState<number | null>(null);
  const [isResizingThisWeek, setIsResizingThisWeek] = useState(false);
  const thisWeekResizeStartY = useRef<number>(0);
  const thisWeekResizeStartHeight = useRef<number>(0);
  
