  const row1TaskRef = useRef<HTMLDivElement>(null);
  const row1CodeRef = useRef<HTMLDivElement>(null);
  const row1CourseRef = useRef<HTMLDivElement>(null);
  const row1DueRef = useRef<HTMLDivElement>(null);
  const row1DaysRef = useRef<HTMLDivElement>(null);
  const row1ProgressBarRef = useRef<HTMLDivElement>(null);
  const row1ContainerRef = useRef<HTMLDivElement>(null);
  // HARDCODED header positions - NEVER change without explicit user permission
  // remaining=25, task=75, code=177, course=214, due=365, days=right-aligned to right edge
  const HEADER_POS = { remaining: 25, task: 77, code: 187, course: 230, due: 367 };
  const [row1Positions, setRow1Positions] = useState({ task: 70, code: 166, course: 234, due: 331, days: 400, progressBar: 18, progressBarTop: 0 });
  
  // Save box order to localStorage
  useEffect(() => {
    localStorage.setItem('boxOrder', JSON.stringify(boxOrder));
  }, [boxOrder]);
  
  const handleBoxDragStart = (boxId: string) => {
    setDraggedBox(boxId);
  };
  
  const handleBoxDragOver = (e: React.DragEvent, targetBoxId: string) => {
    e.preventDefault();
    if (draggedBox && draggedBox !== targetBoxId) {
      const newOrder = [...boxOrder];
      const draggedIdx = newOrder.indexOf(draggedBox);
      const targetIdx = newOrder.indexOf(targetBoxId);
      newOrder.splice(draggedIdx, 1);
      newOrder.splice(targetIdx, 0, draggedBox);
      setBoxOrder(newOrder);
    }
  };
  
  const handleBoxDragEnd = () => {
    setDraggedBox(null);
  };

  // This Week box resize handlers
  const handleThisWeekResizeStart = (e: React.MouseEvent | React.TouchEvent) => {
    e.preventDefault();
    const { clientY } = getPointerXY(e);
    setIsResizingThisWeek(true);
    thisWeekResizeStartY.current = clientY;
    const section = (e.target as HTMLElement).closest('section');
    thisWeekResizeStartHeight.current = section?.offsetHeight || 125;
  };

  useEffect(() => {
    if (!isResizingThisWeek) return;
    
    const handleMove = (e: MouseEvent | TouchEvent) => {
      const { clientY } = getPointerXY(e);
      const deltaY = clientY - thisWeekResizeStartY.current;
      const newHeight = Math.max(85, thisWeekResizeStartHeight.current + deltaY);
      setThisWeekBoxHeight(newHeight);
    };
    
    const handleEnd = () => {
      setIsResizingThisWeek(false);
    };
    
    document.addEventListener('mousemove', handleMove);
    document.addEventListener('mouseup', handleEnd);
    document.addEventListener('touchmove', handleMove, { passive: false });
    document.addEventListener('touchend', handleEnd);
    return () => {
      document.removeEventListener('mousemove', handleMove);
      document.removeEventListener('mouseup', handleEnd);
      document.removeEventListener('touchmove', handleMove);
      document.removeEventListener('touchend', handleEnd);
    };
  }, [isResizingThisWeek]);

  const [profileData, setProfileData] = useState<{ firstName: string; lastName: string; birthdate: string; timezone: string; travelTimezone: string | null; postalCode: string; location: string; phoneNumber: string; email: string; address: string; country: string; provinceState: string; emergencyContactName: string; emergencyContactPhone: string; allergies: string }>(() => {
    const saved = localStorage.getItem('profileData');
    return saved ? { postalCode: '', location: '', phoneNumber: '', email: '', address: '', country: '', provinceState: '', emergencyContactName: '', emergencyContactPhone: '', allergies: '', ...JSON.parse(saved) } : { firstName: 'Bryn', lastName: 'Kai-Hendricks', birthdate: '', timezone: 'America/Toronto', travelTimezone: null, postalCode: '', location: '', phoneNumber: '', email: '', address: '', country: '', provinceState: '', emergencyContactName: '', emergencyContactPhone: '', allergies: '' };
  });
  const [schoolData, setSchoolData] = useState<{ schoolLogo: string | null; schoolName: string; numberOfWeeks: number; week1StartDate: string; firstDayOfWeek: string; lastDayOfSchoolWeek: string; timezone: string; isTravelling?: boolean; travelTimezone?: string; travelStartDate?: string; travelEndDate?: string }>(() => {
    const saved = localStorage.getItem('schoolData');
    if (saved) {
      const parsed = JSON.parse(saved);
      if (!parsed.lastDayOfSchoolWeek) parsed.lastDayOfSchoolWeek = 'friday';
      return { schoolName: 'Toronto Metropolitan University', ...parsed };
    }
    return { schoolLogo: null, schoolName: 'Toronto Metropolitan University', numberOfWeeks: 13, week1StartDate: '2026-01-12', firstDayOfWeek: 'saturday', lastDayOfSchoolWeek: 'friday', timezone: Intl.DateTimeFormat().resolvedOptions().timeZone || 'America/Toronto' };
  });

  useEffect(() => {
    if (schoolData.isTravelling) {
      if (schoolData.travelEndDate) {
        const rawEnd = schoolData.travelEndDate;
        const endDate = rawEnd.includes('T') ? new Date(rawEnd) : new Date(rawEnd + 'T23:59:59');
        if (new Date() > endDate) {
          const updated = { ...schoolData, isTravelling: false, travelTimezone: undefined, travelStartDate: undefined, travelEndDate: undefined };
          setSchoolData(updated);
          localStorage.setItem('schoolData', JSON.stringify(updated));
          saveDegreeToServer('schoolData', updated);
          setProfileData(prev => {
            const updatedProfile = { ...prev, travelTimezone: null };
            localStorage.setItem('profileData', JSON.stringify(updatedProfile));
            return updatedProfile;
          });
          fetch('/api/travelling', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ isTravelling: false, startDate: null, endDate: null }),
          }).catch(err => console.error('Failed to sync travel expiry:', err));
          console.log('Travel mode auto-ended: travel end date has passed');
          return;
        }
      }
      fetch('/api/travelling', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          isTravelling: true,
          startDate: schoolData.travelStartDate || null,
          endDate: schoolData.travelEndDate || null,
        }),
      }).catch(err => console.error('Failed to sync initial travelling state:', err));
    }
  }, []);

  // Derive last school day from firstDayOfWeek (separator goes between last day and first day)
  const lastSchoolDayIndex = (() => {
    const dayMap: Record<string, number> = { sunday: 0, monday: 1, tuesday: 2, wednesday: 3, thursday: 4, friday: 5, saturday: 6 };
    const firstDayIdx = dayMap[schoolData.firstDayOfWeek] ?? 6;
    return firstDayIdx === 0 ? 6 : firstDayIdx - 1;
  })();

  // Progress column grid position (1-based, accounting for time column and optional module column)
  const saturdayGridCol = (gridSizes.moduleColumnWidth > 0 ? 2 : 1) + lastSchoolDayIndex + 1 + 1;

  const DAY_COL_LEFT_REDUCTION = 10;
  const getGridTemplateColumns = () => {
    const allDays = gridSizes.dayColumnWidths.map(w => `${w}fr`).join(' ');
    if (gridSizes.moduleColumnWidth > 0) {
      return `${gridSizes.timeColumnWidth}px ${gridSizes.moduleColumnWidth + 9}px ${allDays}`;
    }
    return `${gridSizes.timeColumnWidth}px ${allDays}`;
  };

  const [coursesData, setCoursesData] = useState<{ courses: Array<{ name: string; color: string; colorEnd?: string; colorStops?: string; borderColor?: string; courseRowColor?: string; taskBgColor?: string; professor: string; professorEmail?: string }> }>(() => {
    const defaultCourses = [
      { name: 'CPPA122 - Local Politics and Government', color: '#0F5004', colorEnd: '#47B045', professor: 'Caryl Arundel', professorEmail: 'carundel@torontomu.ca' },
      { name: 'CFNF400 - Human Sexuality', color: '#DE1864', colorEnd: '#FA67B3', professor: 'Alex McKay', professorEmail: 'a4mckay@torontomu.ca' },
      { name: 'CASL101 - ASL', color: '#974B8A', colorEnd: '#B045A2', professor: 'Christina Moreau', professorEmail: 'christina.moreau@torontomu.ca' },
      { name: 'CECN210 - Understanding Economics', color: '#059669', colorEnd: '#34D399', professor: '', professorEmail: '' },
      { name: 'CPHL110 - Philosophy of Religion', color: '#2563EB', colorEnd: '#60A5FA', professor: '', professorEmail: '' },
      { name: 'CHIS105 - Inventing Popular Culture', color: '#DC2626', colorEnd: '#F87171', professor: '', professorEmail: '' },
      { name: 'CPPA235 - Issues in Canadian Politics', color: '#8B6914', colorEnd: '#CD853F', professor: '', professorEmail: '' },
      { name: '', color: '#6b7280', colorEnd: '#9ca3af', professor: '', professorEmail: '' },
      { name: '', color: '#6b7280', colorEnd: '#9ca3af', professor: '', professorEmail: '' },
      { name: '', color: '#6b7280', colorEnd: '#9ca3af', professor: '', professorEmail: '' },
      { name: '', color: '#6b7280', colorEnd: '#9ca3af', professor: '', professorEmail: '' },
    ];
    // Always use defaults for professor emails to ensure they stay current
    const saved = localStorage.getItem('coursesData');
    if (saved) {
      const parsed = JSON.parse(saved);
      const hasNamedCourses = parsed.courses?.some((c: { name: string }) => c.name.trim());
      if (hasNamedCourses) {
        const coursesWithProfessor = parsed.courses.map((c: { name: string; color: string; colorEnd?: string; professor?: string; professorEmail?: string }, i: number) => ({
          ...c,
          name: c.name?.trim() ? c.name : defaultCourses[i]?.name ?? '',
          color: c.color || defaultCourses[i]?.color || '#6b7280',
          colorEnd: c.colorEnd || defaultCourses[i]?.colorEnd || '',
          professor: c.professor ?? defaultCourses[i]?.professor ?? '',
          professorEmail: defaultCourses[i]?.professorEmail ?? ''
        }));
        const savedNames = coursesWithProfessor.map((c: { name: string }) => c.name?.split(' - ')[0]?.trim().toUpperCase()).filter(Boolean);
        for (const dc of defaultCourses) {
          if (dc.name && !savedNames.includes(dc.name.split(' - ')[0]?.trim().toUpperCase())) {
            const emptyIdx = coursesWithProfessor.findIndex((c: { name: string }) => !c.name?.trim());
            if (emptyIdx >= 0) {
              coursesWithProfessor[emptyIdx] = { ...dc };
            } else {
              coursesWithProfessor.push({ ...dc });
            }
          }
        }
        localStorage.setItem('coursesData', JSON.stringify({ courses: coursesWithProfessor }));
        return { courses: coursesWithProfessor };
      }
      return { courses: defaultCourses };
    }
    return { courses: defaultCourses };
  });
