  const saveSchool = (data: { schoolLogo: string | null; schoolName: string; numberOfWeeks: number; week1StartDate: string; firstDayOfWeek: string; lastDayOfSchoolWeek: string; timezone: string; isTravelling?: boolean; travelTimezone?: string; travelStartDate?: string; travelEndDate?: string; semesterType?: string }) => {
    const { semesterType: semType, ...schoolOnly } = data;
    setSchoolData(schoolOnly);
    localStorage.setItem('schoolData', JSON.stringify(schoolOnly));
    saveDegreeToServer('schoolData', schoolOnly);
    if (semType && semesterSettings) {
      saveSemesterScheduleMutation.mutate({ semesterType: semType });
    }
    fetch('/api/travelling', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        isTravelling: !!data.isTravelling,
        startDate: data.travelStartDate || null,
        endDate: data.travelEndDate || null,
      }),
    }).catch(err => console.error('Failed to sync travelling state:', err));
    toast({ title: "School settings saved", description: "Your school settings have been updated." });
  };
  
  const saveCourses = (data: { courses: Array<{ name: string; color: string; colorEnd?: string; colorStops?: string; borderColor?: string; courseRowColor?: string; taskBgColor?: string; professor: string; professorEmail?: string }> }) => {
    const prevCourses = coursesData?.courses || [];
    setCoursesData(data);
    localStorage.setItem('coursesData', JSON.stringify(data));
    saveDegreeToServer('coursesData', data);
    setIsCoursesDialogOpen(false);
    toast({ title: "Courses saved", description: "Your courses have been updated." });
    const semPayload: Record<string, string | null> = {};
    for (let i = 0; i < 3; i++) {
      const course = data.courses[i] as any;
      const prefix = `course${i + 1}`;
      if (course) {
        semPayload[`${prefix}Color`] = course.color || null;
        semPayload[`${prefix}ColorEnd`] = course.colorEnd || null;
        semPayload[`${prefix}ColorStops`] = course.colorStops || null;
        semPayload[`${prefix}BorderColor`] = course.borderColor || null;
        semPayload[`${prefix}CourseRowColor`] = course.courseRowColor || null;
        semPayload[`${prefix}TaskBgColor`] = course.taskBgColor || null;
        const parts = course.name.split(' - ');
        const code = (parts[0] || '').trim();
        const name = parts.slice(1).join(' - ').trim();
        semPayload[`${prefix}Code`] = code || null;
        semPayload[`${prefix}Name`] = course.name || null;
        semPayload[`${prefix}Professor`] = course.professor || null;
        semPayload[`${prefix}ProfessorEmail`] = course.professorEmail || null;
      } else {
        semPayload[`${prefix}Color`] = null;
        semPayload[`${prefix}ColorEnd`] = null;
        semPayload[`${prefix}Code`] = null;
        semPayload[`${prefix}Name`] = null;
      }
    }
    fetch('/api/semester', { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, credentials: 'include', body: JSON.stringify(semPayload) })
      .then(() => {
        queryClient.invalidateQueries({ queryKey: ["/api/semester"] });
        queryClient.invalidateQueries({ queryKey: ["/api/semesters"] });
      })
      .catch(() => {});

    for (let i = 0; i < 3; i++) {
      const newCourse = data.courses[i];
      const oldCourse = prevCourses[i];
      if (!newCourse?.name?.trim()) continue;
      const newParts = newCourse.name.split(' - ');
      const newCode = (newParts[0] || '').trim();
      const newName = newParts.slice(1).join(' - ').trim();
      const oldParts = (oldCourse?.name || '').split(' - ');
      const oldCode = (oldParts[0] || '').trim();
      const oldName = oldParts.slice(1).join(' - ').trim();
      if (newCode && (newCode !== oldCode || newName !== oldName)) {
        fetch('/api/onedrive/rename-course-folder', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          credentials: 'include',
          body: JSON.stringify({
            courseIndex: i + 1,
            oldCode: oldCode || newCode,
            oldName: oldName,
            newCode,
            newName,
          }),
        }).catch(() => {});
      }
    }
  };

