  const courseWeekVariants = useMemo(() => {
    const variants: Record<number, { courseCode: string; label: string }[]> = {};
    for (const m of allCourseWeekMappings) {
      if (m.courseWeekLabel && m.courseWeekLabel.trim()) {
        if (!variants[m.weekNumber]) variants[m.weekNumber] = [];
        variants[m.weekNumber].push({ courseCode: m.courseCode, label: m.courseWeekLabel });
      }
    }
    return variants;
  }, [allCourseWeekMappings]);

  // Automatically set selectedWeek based on today's date (re-checks when date changes)
  const lastAutoWeekDateRef = useRef(new Date().getDate());
  useEffect(() => {
    if (weeks.length > 0) {
      const today = new Date();
      const todayDateOnly = new Date(today.getFullYear(), today.getMonth(), today.getDate());
      const currentWeek = weeks.find(w => {
        const start = parseISO(w.startDate);
        const end = parseISO(w.endDate);
        const startDateOnly = new Date(start.getFullYear(), start.getMonth(), start.getDate());
        const endDateOnly = new Date(end.getFullYear(), end.getMonth(), end.getDate());
        return todayDateOnly >= startDateOnly && todayDateOnly <= endDateOnly;
      });
      if (currentWeek) {
        setSelectedWeek(currentWeek.weekNumber);
      } else {
        const cachedSem = queryClient.getQueryData<SemesterSettings | null>(["/api/semester"]);
        const semStart = cachedSem?.semesterStartDate ? new Date(cachedSem.semesterStartDate) : undefined;
        const readingWeek = cachedSem?.readingWeekStart || null;
        const computedWeek = getWeekNumber(today, semStart, readingWeek);
        setSelectedWeek(computedWeek);
      }
      lastAutoWeekDateRef.current = today.getDate();
    }
  }, [weeks]);

  useEffect(() => {
    if (weeks.length === 0) return;
    const currentDate = currentTime.getDate();
    if (currentDate !== lastAutoWeekDateRef.current) {
      lastAutoWeekDateRef.current = currentDate;
      const todayDateOnly = new Date(currentTime.getFullYear(), currentTime.getMonth(), currentTime.getDate());
      const currentWeek = weeks.find(w => {
        const start = parseISO(w.startDate);
        const end = parseISO(w.endDate);
        const startDateOnly = new Date(start.getFullYear(), start.getMonth(), start.getDate());
        const endDateOnly = new Date(end.getFullYear(), end.getMonth(), end.getDate());
        return todayDateOnly >= startDateOnly && todayDateOnly <= endDateOnly;
      });
      if (currentWeek) {
        setSelectedWeek(currentWeek.weekNumber);
      } else {
        const cachedSem = queryClient.getQueryData<SemesterSettings | null>(["/api/semester"]);
        const semStart = cachedSem?.semesterStartDate ? new Date(cachedSem.semesterStartDate) : undefined;
        const readingWeek = cachedSem?.readingWeekStart || null;
        const computedWeek = getWeekNumber(currentTime, semStart, readingWeek);
        setSelectedWeek(computedWeek);
      }
    }
  }, [currentTime, weeks]);

  const { data: allTasks = [] } = useQuery<Task[]>({
    queryKey: ["/api/tasks"],
    queryFn: () => fetch("/api/tasks", { credentials: 'include' }).then(r => { if (!r.ok) throw new Error(r.statusText); return r.json(); }),
    retry: 2,
    retryDelay: 1000,
  });

  const hasUnackedReminders = allTasks.some((t: any) => t.type === 'reminder' && t.isAcknowledged === false && !t.isCompleted);

  useEffect(() => {
    if (!allTasks || allTasks.length === 0) return;
    const courseTasksMap: Record<string, Task[]> = {};
    for (const t of allTasks) {
      if (!t.courseName) continue;
      const cn = t.courseName.split(' - ')[0]?.trim().replace(/\s/g, '').toUpperCase();
      if (!cn) continue;
      if (!courseTasksMap[cn]) courseTasksMap[cn] = [];
      courseTasksMap[cn].push(t);
    }
    const updates: Record<string, { grade: string; percent: string }> = {};
    for (const [cn, tasks] of Object.entries(courseTasksMap)) {
      const graded = tasks.filter(t => t.gradeWeight && t.gradeTotal && t.gradeValue !== null && t.gradeValue !== undefined);
      if (graded.length === 0) continue;
      let wSum = 0, wTotal = 0;
      for (const t of graded) {
        const pct = (t.gradeValue! / t.gradeTotal!) * 100;
        wSum += pct * (t.gradeWeight! / 100);
        wTotal += t.gradeWeight!;
      }
      if (wTotal <= 0) continue;
      const currentPercent = Math.round((wSum / wTotal) * 1000) / 10;
      const grade = percentToGrade(String(currentPercent));
      for (const [ck, info] of Object.entries(certCourseMap)) {
        const mapCode = info.code.replace(/\s/g, '').toUpperCase();
        if (mapCode === cn || cn.endsWith(mapCode) || mapCode.endsWith(cn.replace(/^C/, ''))) {
          if (!shouldStrikethrough(ck)) {
            updates[ck] = { grade, percent: String(currentPercent) };
          }
        }
      }
    }
    const strikeClearKeys: string[] = [];
    for (const ck of Object.keys(certCourseMap)) {
      if (shouldStrikethrough(ck)) strikeClearKeys.push(ck);
    }
    if (Object.keys(updates).length > 0 || strikeClearKeys.length > 0) {
      setCourseGrades(prev => {
        const merged = { ...prev };
        let changed = false;
        for (const [k, v] of Object.entries(updates)) {
          if (!merged[k]?.percent || merged[k].percent.trim() === '') {
            merged[k] = v;
            changed = true;
          }
        }
        for (const sk of strikeClearKeys) {
          if (merged[sk]?.percent && merged[sk].percent.trim() !== '') {
            const isDefault = ['PPA101', 'PPA102', 'PPA125', 'L1_PPA120', 'L1_PPA121', 'LIBERAL'].includes(sk);
            if (!isDefault) {
              delete merged[sk];
              changed = true;
            }
          }
        }
        if (!changed) return prev;
        localStorage.setItem('courseGrades', JSON.stringify(merged));
        return merged;
      });
    }
  }, [allTasks]);

  useEffect(() => {
    const defaultKeys = new Set(['PPA101', 'PPA102', 'PPA125', 'L1_PPA120', 'L1_PPA121', 'LIBERAL']);
    setCourseGrades(prev => {
      const cleaned = { ...prev };
      let changed = false;
      for (const ck of Object.keys(cleaned)) {
        if (defaultKeys.has(ck)) continue;
        if (shouldStrikethrough(ck) && cleaned[ck]?.percent && cleaned[ck].percent.trim() !== '') {
          delete cleaned[ck];
          changed = true;
        }
      }
      if (!changed) return prev;
      localStorage.setItem('courseGrades', JSON.stringify(cleaned));
      return cleaned;
    });
  }, []);

  useEffect(() => {
    const measure = () => {
      const els = document.querySelectorAll('[data-upcoming-task-name]');
      if (!els.length) return;
      let max = 0;
      els.forEach(el => {
        const range = document.createRange();
        range.selectNodeContents(el);
        const w = range.getBoundingClientRect().width;
        if (w > max) max = w;
      });
      if (max > 0) setMaxTaskNameWidth(Math.ceil(max));
    };
    requestAnimationFrame(() => setTimeout(measure, 50));
    const t2 = setTimeout(measure, 300);
    const t3 = setTimeout(measure, 800);
    return () => { clearTimeout(t2); clearTimeout(t3); };
  }, [allTasks, selectedWeek]);

  const { data: tasks = [], isLoading } = useQuery<Task[]>({
    queryKey: ["/api/tasks", { weekNumber: selectedWeek }],
    queryFn: () => fetch(`/api/tasks?weekNumber=${selectedWeek}`, { credentials: 'include' }).then(r => { if (!r.ok) throw new Error(r.statusText); return r.json(); }),
    retry: 2,
    retryDelay: 1000,
  });

  // Fetch all projects for calendar display
