  useEffect(() => { semesterSettingsRef.current = semesterSettings ?? null; }, [semesterSettings]);

  const { data: allSemesterSettings } = useQuery<any[]>({
    queryKey: ["/api/semesters"],
    queryFn: () => fetch("/api/semesters", { credentials: 'include' }).then(r => { if (!r.ok) throw new Error(r.statusText); return r.json(); }),
  });
  const allSemesterSettingsRef = useRef(allSemesterSettings);
  allSemesterSettingsRef.current = allSemesterSettings;

  useEffect(() => {
    if (!semesterSettings) return;
    const sem = semesterSettings as any;
    setCoursesData(prev => {
      const updated = [...prev.courses];
      let changed = false;
      for (let i = 0; i < 3; i++) {
        const prefix = `course${i + 1}`;
        const semColor = sem[`${prefix}Color`];
        const semColorEnd = sem[`${prefix}ColorEnd`];
        const semColorStops = sem[`${prefix}ColorStops`];
        const semBorderColor = sem[`${prefix}BorderColor`];
        const semCourseRowColor = sem[`${prefix}CourseRowColor`];
        const semTaskBgColor = sem[`${prefix}TaskBgColor`];
        if (updated[i]) {
          const c = updated[i] as any;
          if (semColor && semColor !== c.color) { c.color = semColor; changed = true; }
          if (semColorEnd && semColorEnd !== c.colorEnd) { c.colorEnd = semColorEnd; changed = true; }
          if (semColorStops !== undefined && semColorStops !== null && semColorStops !== c.colorStops) { c.colorStops = semColorStops; changed = true; }
          if (semBorderColor !== undefined && semBorderColor !== null && semBorderColor !== c.borderColor) { c.borderColor = semBorderColor; changed = true; }
          if (semCourseRowColor !== undefined && semCourseRowColor !== null && semCourseRowColor !== c.courseRowColor) { c.courseRowColor = semCourseRowColor; changed = true; }
          if (semTaskBgColor !== undefined && semTaskBgColor !== null && semTaskBgColor !== c.taskBgColor) { c.taskBgColor = semTaskBgColor; changed = true; }
        }
      }
      if (changed) {
        const newData = { courses: updated };
        localStorage.setItem('coursesData', JSON.stringify(newData));
        return newData;
      }
      return prev;
    });
  }, [semesterSettings]);

  const [deliveryModeVersion, setDeliveryModeVersion] = useState(0);
  const courseDeliveryModes = useMemo(() => {
    const map: Record<string, string> = {};
    try {
      const cd = localStorage.getItem('certCourseData');
      if (cd) {
        const sd = JSON.parse(cd);
        for (const [key, val] of Object.entries(sd)) {
          if ((val as any)?.deliveryMode) {
            map[key.replace(/\s/g, '')] = (val as any).deliveryMode;
          }
        }
      }
    } catch {}
    if (allSemesterSettings) {
      for (const sem of allSemesterSettings) {
        for (let i = 1; i <= 3; i++) {
          const code = (sem[`course${i}Code`] || '').replace(/\s/g, '');
          const mode = sem[`course${i}DeliveryMode`] || '';
          if (code && mode) map[code] = mode;
        }
      }
    }
    return map;
  }, [allSemesterSettings, deliveryModeVersion]);

  useEffect(() => {
    if (!semesterSettings) return;
    const dbColors: Record<number, { color?: string; colorEnd?: string; colorStops?: string }> = {};
    for (let i = 1; i <= 3; i++) {
      const c = (semesterSettings as any)[`course${i}Color`];
      const ce = (semesterSettings as any)[`course${i}ColorEnd`];
      const cs = (semesterSettings as any)[`course${i}ColorStops`];
      if (c) dbColors[i - 1] = { color: c, colorEnd: ce || undefined, colorStops: cs || undefined };
    }
    if (Object.keys(dbColors).length > 0) {
      setCoursesData(prev => {
        const updated = { ...prev, courses: prev.courses.map((course, idx) => {
          const db = dbColors[idx];
          if (db) return { ...course, color: db.color || course.color, colorEnd: db.colorEnd || course.colorEnd, colorStops: db.colorStops || course.colorStops };
          return course;
        })};
        localStorage.setItem('coursesData', JSON.stringify(updated));
        saveDegreeToServer('coursesData', updated);
        return updated;
      });
    }
  }, [semesterSettings]);

  useEffect(() => {
    try {
      const cd = localStorage.getItem('certCourseData');
      if (!cd) return;
      const savedData = JSON.parse(cd);
      let changed = false;
      for (const course of coursesData.courses) {
        if (!course.name?.trim()) continue;
        const code = course.name.split(' - ')[0]?.trim();
        if (savedData[code] && course.color) {
          if (savedData[code].color !== course.color || savedData[code].colorEnd !== (course.colorEnd || '')) {
            savedData[code].color = course.color;
            savedData[code].colorEnd = course.colorEnd || '';
            changed = true;
          }
        }
      }
      if (changed) {
        localStorage.setItem('certCourseData', JSON.stringify(savedData));
        saveDegreeToServer('certCourseData', savedData);
      }
    } catch {}
  }, [coursesData]);

  useEffect(() => {
    const synced = sessionStorage.getItem('professorContactsSynced');
    if (synced) return;
    sessionStorage.setItem('professorContactsSynced', '1');
    for (const course of coursesData.courses) {
      if (course.professor?.trim()) {
        const code = course.name.split(' - ')[0]?.trim();
        fetch('/api/key-contacts/sync-professor', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ professorName: course.professor, professorEmail: course.professorEmail, courseCode: code }),
        }).catch(() => {});
      }
    }
    const syncedNames = new Set(coursesData.courses.filter(c => c.professor?.trim()).map(c => c.professor!.toLowerCase()));
    try {
      const certData = localStorage.getItem('certCourseData');
      if (certData) {
        const savedData = JSON.parse(certData);
        const currentCodes = new Set(coursesData.courses.map(c => c.name.split(' - ')[0]?.trim().toUpperCase().replace(/\s/g, '')));
        for (const [certKey, info] of Object.entries(savedData)) {
          const ci = info as any;
          if (ci.professor?.trim() && !currentCodes.has(certKey.toUpperCase().replace(/\s/g, ''))) {
            syncedNames.add(ci.professor.toLowerCase());
            fetch('/api/key-contacts/sync-professor', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ professorName: ci.professor, professorEmail: ci.professorEmail || '', courseCode: certKey }),
            }).catch(() => {});
          }
        }
      }
    } catch {}
  }, []);

  useEffect(() => {
    if (!pastCourseInfo || Object.keys(pastCourseInfo).length === 0) return;
    const synced = sessionStorage.getItem('pastProfContactsSynced');
    if (synced) return;
    sessionStorage.setItem('pastProfContactsSynced', '1');
    const existingNames = new Set(coursesData.courses.filter(c => c.professor?.trim()).map(c => c.professor!.toLowerCase()));
    try {
      const certData = localStorage.getItem('certCourseData');
      if (certData) {
        for (const info of Object.values(JSON.parse(certData))) {
          const ci = info as any;
          if (ci.professor?.trim()) existingNames.add(ci.professor.toLowerCase());
        }
      }
    } catch {}
    for (const [courseKey, info] of Object.entries(pastCourseInfo)) {
      if (info.professor?.trim() && !existingNames.has(info.professor.toLowerCase())) {
        existingNames.add(info.professor.toLowerCase());
        fetch('/api/key-contacts/sync-professor', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ professorName: info.professor, professorEmail: info.email || '', courseCode: courseKey }),
        }).catch(() => {});
      }
    }
  }, [pastCourseInfo]);

  useEffect(() => {
    if (!semesterSettings || semesterChecklistShownRef.current) return;

    const now = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Toronto' }));
    const lastShownKey = `semChecklist_lastShown_${semesterSettings.id}`;
    const snoozeUntilKey = `semChecklist_snoozeUntil_${semesterSettings.id}`;
    const allDoneKey = `semChecklist_allDone_${semesterSettings.id}`;
    if (localStorage.getItem(allDoneKey) === 'true') return;
    const snoozeUntil = parseInt(localStorage.getItem(snoozeUntilKey) || '0', 10);
    if (snoozeUntil && now.getTime() < snoozeUntil) return;
    const lastShown = parseInt(localStorage.getItem(lastShownKey) || '0', 10);
    const hoursSinceShown = (now.getTime() - lastShown) / (1000 * 60 * 60);

    if (hoursSinceShown < 8) return;

    fetch('/api/semester-checklist', { credentials: 'include' })
      .then(r => r.json())
      .then(data => {
        if (data.allChecked) {
          localStorage.setItem(allDoneKey, 'true');
          return;
        }
        setSemesterChecklistItems(data.items);
        setSemesterChecklistId(data.semesterId);
        setShowSemesterChecklist(true);
        localStorage.setItem(lastShownKey, String(now.getTime()));
        semesterChecklistShownRef.current = true;
      })
      .catch(err => console.error('Error fetching semester checklist:', err));
  }, [semesterSettings]);

  useEffect(() => {
    if (confirmSemesterShownRef.current) return;
    const upcoming = getUpcomingSemesterToConfirm();
    if (!upcoming) return;

    const dismissedKey = `semConfirm_dismissed_${upcoming.label}`;
    const dismissed = localStorage.getItem(dismissedKey);
    if (dismissed === 'confirmed') return;

    const lastShownKey = `semConfirm_lastShown_${upcoming.label}`;
    const lastShown = parseInt(localStorage.getItem(lastShownKey) || '0', 10);
    const now = Date.now();
    const hoursSinceShown = (now - lastShown) / (1000 * 60 * 60);
    if (hoursSinceShown < 12) return;

    setUpcomingSemester(upcoming);
    setConfirmSemesterForm({ startDate: upcoming.startDate, endDate: upcoming.endDate, breakStart: upcoming.breakStart, breakEnd: upcoming.breakEnd });
    setShowConfirmSemesterDialog(true);
    localStorage.setItem(lastShownKey, String(now));
    confirmSemesterShownRef.current = true;
  }, []);

  useEffect(() => {
    const todaySemester = getNextSemesterByStartDate();
    if (!todaySemester) return;
    const resetKey = `semReset_done_${todaySemester.label}`;
    if (localStorage.getItem(resetKey)) return;

    fetch('/api/semester-reset-files', { method: 'POST', credentials: 'include' })
      .then(r => r.json())
      .then(data => {
        if (data.success) {
          console.log(`[Semester Start] Reset ${data.resetCount} files for ${todaySemester.label}`);
          localStorage.setItem(resetKey, 'true');
        }
      })
      .catch(err => console.error('Error resetting files for new semester:', err));
  }, []);

  useEffect(() => {
    if (!semesterSettings || pdfUploadShownRef.current) return;
    const now = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Toronto' }));
    const semStart = semesterSettings.semesterStartDate ? new Date(semesterSettings.semesterStartDate) : null;
    if (!semStart) return;
    const daysUntilStart = Math.floor((semStart.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
    if (daysUntilStart < 0 || daysUntilStart > 7) return;
    const lastShownKey = `pdfUpload_lastShown_${semesterSettings.id}`;
    const lastShown = parseInt(localStorage.getItem(lastShownKey) || '0', 10);
    const hoursSinceShown = (now.getTime() - lastShown) / (1000 * 60 * 60);
    if (hoursSinceShown < 336) return;
    setShowPdfUploadDialog(true);
    localStorage.setItem(lastShownKey, String(now.getTime()));
    pdfUploadShownRef.current = true;
  }, [semesterSettings]);

  // Deleted folders query for hamburger menu filtering
