              queryClient.invalidateQueries();
              queryClient.refetchQueries();
              refreshFileCounts();
              fetch('/api/google/calendar/events').catch(() => {});
              fetch('/api/tasks').catch(() => {});
              fetch('/api/announcements').catch(() => {});
