                              if (wc >= 66 && wc <= 67) return <svg width={s} height={s} viewBox="0 0 24 24" fill="none"><path d="M6 11a4.5 4.5 0 0 1 4.5-4.5h2.5a3.5 3.5 0 0 1 0 7H7.5a3 3 0 0 1 0-6" fill="rgba(255,255,255,0.8)"/><g stroke="#93c5fd" strokeWidth="1.5" strokeLinecap="round"><line x1="8" y1="16" x2="7" y2="19"/><line x1="14" y1="16" x2="13" y2="19"/></g></svg>;
                              if (wc >= 71 && wc <= 77) return <svg width={s} height={s} viewBox="0 0 24 24" fill="none"><path d="M6 11a4.5 4.5 0 0 1 4.5-4.5h2.5a3.5 3.5 0 0 1 0 7H7.5a3 3 0 0 1 0-6" fill="rgba(255,255,255,0.8)"/><g fill="#dbeafe"><circle cx="8" cy="17" r="1.5"/><circle cx="13" cy="18" r="1.5"/><circle cx="17" cy="16.5" r="1.5"/></g></svg>;
                              if (wc >= 85 && wc <= 86) return <svg width={s} height={s} viewBox="0 0 24 24" fill="none"><path d="M6 11a4.5 4.5 0 0 1 4.5-4.5h2.5a3.5 3.5 0 0 1 0 7H7.5a3 3 0 0 1 0-6" fill="rgba(255,255,255,0.8)"/><g fill="#dbeafe"><circle cx="7" cy="17" r="1.5"/><circle cx="11" cy="18.5" r="1.5"/><circle cx="15" cy="17" r="1.5"/><circle cx="9" cy="20" r="1.2"/></g></svg>;
                              if (wc >= 95) return <svg width={s} height={s} viewBox="0 0 24 24" fill="none"><path d="M6 10a4.5 4.5 0 0 1 4.5-4.5h2.5a3.5 3.5 0 0 1 0 7H7.5a3 3 0 0 1 0-6" fill="rgba(200,200,200,0.9)"/><path d="M13 14l-2 4h3l-2 4" stroke="#facc15" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/></svg>;
