                                  <div className="text-[8px] font-bold tracking-wide" style={{ color: isNextSchoolWeek ? 'rgba(255,255,255,0.4)' : '#ffffff', lineHeight: 1, textTransform: 'uppercase' }}>{format(day, 'MMM')}</div>
